@@ -1,3 +1,11 @@
+const MAX_TIMEOUT_MS = 2 ** 31 - 1;
+const MIN_REFRESH_DELAY_MS = 30000;
+const REFRESH_JITTER_MS = 30000;
+
+/**
+ * Attributes used when clearing the session cookie. The server owns the cookie's
+ * lifetime, so no maxAge is ever set from the client.
+ */
 export function getTokenCookieOptions() {
   const { $appInfo } = useNuxtApp();

@@ -5,9 +13,54 @@ export function getTokenCookieOptions() {
   const isEmbedded = isSecureConnection && window?.self !== window?.top;

   return {
-    maxAge: $appInfo.tokenTime * 60 * 60,
     secure: isSecureConnection,
     sameSite: (isEmbedded ? "none" : "lax") as "none" | "lax",
     partitioned: isEmbedded,
   };
 }
+
+/** The JWT's exp claim in epoch milliseconds, or null if the token can't be decoded. */
+export function getTokenExpiry(token: string): number | null {
+  try {
+    const payload = token.split(".")[1];
+    if (!payload) return null;
+
+    const base64 = payload.replace(/-/g, "+").replace(/_/g, "/");
+    const padded = base64.padEnd(base64.length + ((4 - (base64.length % 4)) % 4), "=");
+    const bytes = Uint8Array.from(atob(padded), c => c.charCodeAt(0));
+    const claims = JSON.parse(new TextDecoder().decode(bytes));
+
+    return typeof claims?.exp === "number" ? claims.exp * 1000 : null;
+  }
+  catch {
+    return null;
+  }
+}
+
+/** The URL-decoded value of exactly the named cookie, or null when it isn't set. */
+export function readTokenCookie(name: string): string | null {
+  if (typeof document === "undefined") return null;
+
+  for (const part of document.cookie.split(";")) {
+    const separator = part.indexOf("=");
+    if (separator === -1) continue;
+    if (part.slice(0, separator).trim() !== name) continue;
+
+    const value = part.slice(separator + 1).trim();
+    try {
+      return decodeURIComponent(value);
+    }
+    catch {
+      return value;
+    }
+  }
+  return null;
+}
+
+/** Milliseconds to wait before refreshing a token with `remainingMs` left, or null if it already expired. */
+export function nextRefreshDelay(remainingMs: number, jitter: number = Math.random()): number | null {
+  if (!(remainingMs > 0)) return null;
+
+  const delay = Math.max((remainingMs * 6) / 10, MIN_REFRESH_DELAY_MS) + jitter * REFRESH_JITTER_MS;
+  return Math.min(delay, MAX_TIMEOUT_MS);
+}
