new file mode 100644
index 0000000..82bc123
--- /dev/null
+++ b/mealie/core/security/tokens.py
@@ -0,0 +1,24 @@
+from datetime import UTC, datetime, timedelta
+
+import jwt
+
+from mealie.core.config import get_app_settings
+
+ALGORITHM = "HS256"
+ISS = "mealie"
+
+
+def create_access_token(data: dict, expires_delta: timedelta | None = None) -> tuple[str, timedelta]:
+    """Signs a JWT; returns the token and the lifetime it was granted."""
+    settings = get_app_settings()
+
+    to_encode = data.copy()
+    expires_delta = expires_delta or timedelta(hours=settings.TOKEN_TIME)
+
+    # issue times are whole seconds, so exp - iat is exactly the lifetime
+    issued_at = datetime.now(UTC).replace(microsecond=0)
+
+    to_encode["iat"] = issued_at
+    to_encode["exp"] = issued_at + expires_delta
+    to_encode["iss"] = ISS
+    return jwt.encode(to_encode, settings.SECRET, algorithm=ALGORITHM), expires_delta
