+from datetime import timedelta
+
+from fastapi.testclient import TestClient
+
+from mealie.core.config import get_app_settings
+from mealie.core.security import create_access_token
+from tests.utils import api_routes
+
+
+def _login(api_client: TestClient, user, remember_me: bool):
+    return api_client.post(
+        api_routes.auth_token,
+        data={"username": user.email, "password": user.password, "remember_me": str(remember_me).lower()},
+    )
+
+
+def test_login_sets_cookie_and_expires_in(api_client: TestClient, unique_user):
+    lifetime = get_app_settings().TOKEN_TIME * 3600
+
+    persistent = _login(api_client, unique_user, True)
+    assert persistent.status_code == 200
+    assert persistent.json()["expires_in"] == lifetime
+    cookie = persistent.headers["set-cookie"]
+    assert cookie.startswith(f"mealie.access_token={persistent.json()['access_token']}")
+    assert f"Max-Age={lifetime}" in cookie
+
+    session_only = _login(api_client, unique_user, False)
+    assert "Max-Age" not in session_only.headers["set-cookie"]
+
+
+def test_refresh_keeps_remember_me_and_rejects_api_tokens(api_client: TestClient, unique_user):
+    token = _login(api_client, unique_user, True).json()["access_token"]
+    response = api_client.post(api_routes.auth_refresh, headers={"Authorization": f"Bearer {token}"})
+    assert response.status_code == 200
+    assert "Max-Age" in response.headers["set-cookie"]
+
+    new_headers = {"Authorization": f"Bearer {response.json()['access_token']}"}
+    assert api_client.get(api_routes.users_self, headers=new_headers).status_code == 200
+    assert api_client.get(api_routes.auth_refresh, headers=new_headers).status_code == 405
+    api_client.cookies.clear()
+    assert api_client.post(api_routes.auth_refresh).status_code == 401
+
+    created = api_client.post(api_routes.users_api_tokens, json={"name": "t"}, headers=new_headers)
+    api_token = created.json()["token"]
+    refused = api_client.post(api_routes.auth_refresh, headers={"Authorization": f"Bearer {api_token}"})
+    assert refused.status_code == 400
+
+
+def test_logout_clears_cookie(api_client: TestClient, unique_user):
+    token = _login(api_client, unique_user, False).json()["access_token"]
+    response = api_client.post(api_routes.auth_logout, headers={"Authorization": f"Bearer {token}"})
+    cookie = response.headers["set-cookie"]
+    assert cookie.startswith("mealie.access_token=")
+    assert "Max-Age=0" in cookie
+
+
+def test_token_lifetime_and_claims():
+    token, lifetime = create_access_token({"sub": "x"}, timedelta(minutes=5))
+    assert lifetime == timedelta(minutes=5)
+
+    import jwt
+
+    claims = jwt.decode(token, options={"verify_signature": False})
+    assert claims["iss"] == "mealie"
