+/** The URL-decoded value of exactly this cookie from document.cookie, or null when it isn't set. */
+export function readTokenCookie(name: string): string | null {
+  for (const part of document.cookie.split(";")) {
+    const separator = part.indexOf("=");
+    if (separator === -1) continue;
+
+    if (part.slice(0, separator).trim() === name) {
+      const value = part.slice(separator + 1).trim();
+      try {
+        return decodeURIComponent(value);
+      }
+      catch {
+        return value;
+      }
+    }
+  }
+  return null;
+}
+
+/** Milliseconds to wait before refreshing a token with `remainingMs` left, or null when it already expired. */
+export function nextRefreshDelay(remainingMs: number, jitter: number = Math.random()): number | null {
+  if (!(remainingMs > 0)) return null;
+
+  const delay = Math.max(remainingMs * 0.6, MIN_REFRESH_DELAY) + jitter * REFRESH_JITTER;
+  return Math.min(delay, MAX_TIMER_DELAY);
+}
