@@ -0,0 +1,23 @@
+from datetime import UTC, datetime, timedelta
+
+import jwt
+
+from mealie.core.config import get_app_settings
+
+ALGORITHM = "HS256"
+ISS = "mealie"
+
+
+def create_access_token(data: dict, expires_delta: timedelta | None = None) -> tuple[str, timedelta]:
+    """Signs a token with the given claims; returns the token and the lifetime it was granted"""
+    settings = get_app_settings()
+
+    lifetime = expires_delta or timedelta(hours=settings.TOKEN_TIME)
+    # issue times are whole seconds, so exp - iat is exactly the lifetime
+    issued_at = int(datetime.now(UTC).timestamp())
+
+    to_encode = data.copy()
+    to_encode["iss"] = ISS
+    to_encode["iat"] = issued_at
+    to_encode["exp"] = issued_at + int(lifetime.total_seconds())
+    return jwt.encode(to_encode, settings.SECRET, algorithm=ALGORITHM), lifetime
