+def session_cookie_attrs(request: Request) -> dict[str, Any]:
+    """Cookie attributes that depend on how the client reached us (scheme, embedding)"""
+    forwarded_proto = request.headers.get("x-forwarded-proto", "").split(",")[0].strip().lower()
+    secure = request.url.scheme == "https" or forwarded_proto == "https"
+
+    # an embedded (cross-site framed) page only gets the cookie when it is partitioned and secure
+    embedded = request.headers.get("x-mealie-embedded", "").strip().lower() == "true"
+    cross_site = secure and embedded
+    return {
+        "secure": secure,
+        "samesite": "none" if cross_site else "lax",
+        "partitioned": cross_site,
+    }
+
+
+def set_session_cookie(request: Request, response: Response, token: str, lifetime: timedelta, persistent: bool) -> None:
+    """
+    The SPA reads the cookie to build its Authorization header, so it is not HttpOnly.
+    Persistent cookies live as long as the token, otherwise they end with the browser session.
+    """
+    response.set_cookie(
+        SESSION_COOKIE_NAME,
+        token,
+        max_age=int(lifetime.total_seconds()) if persistent else None,
+        path="/",
+        httponly=False,
+        **session_cookie_attrs(request),
+    )
+
+
+def token_response(request: Request, response: Response, token: str, lifetime: timedelta, persistent: bool) -> dict:
+    set_session_cookie(request, response, token, lifetime, persistent)
+    return MealieAuthToken.respond(token, lifetime)


