+++ b/tests/integration_tests/user_tests/test_auth_sessions.py
@@ -0,0 +1,92 @@
+import time
+from types import SimpleNamespace
+
+import jwt
+from fastapi.testclient import TestClient
+
+from mealie.core.config import get_app_settings
+from mealie.routes.auth.auth import session_cookie_attrs
+from tests.utils import api_routes
+from tests.utils.fixture_schemas import TestUser
+
+
+def login(api_client: TestClient, user: TestUser, remember_me: bool, password: str | None = None):
+    return api_client.post(
+        api_routes.auth_token,
+        data={"username": user.username, "password": password or user.password, "remember_me": remember_me},
+    )
+
+
+def bearer(token: str) -> dict[str, str]:
+    return {"Authorization": f"Bearer {token}"}
+
+
+def test_login_cookie_and_claims(api_client: TestClient, unique_user: TestUser):
+    settings = get_app_settings()
+    for remember in (True, False):
+        response = login(api_client, unique_user, remember)
+        body = response.json()
+        assert body["expires_in"] == settings.TOKEN_TIME * 3600
+        claims = jwt.decode(body["access_token"], options={"verify_signature": False})
+        assert claims["rme"] is remember
+        assert claims["exp"] - claims["iat"] == body["expires_in"]
+        cookie = response.headers.get_list("set-cookie")[0]
+        assert cookie.startswith(f"mealie.access_token={body['access_token']}")
+        assert "Path=/" in cookie
+        assert ("Max-Age=" in cookie) is remember
+
+
+def test_refresh_keeps_rme_and_refuses_api_tokens(api_client: TestClient, unique_user: TestUser):
+    token = login(api_client, unique_user, True).json()["access_token"]
+    response = api_client.post(api_routes.auth_refresh, headers=bearer(token))
+    assert response.status_code == 200
+    new = response.json()["access_token"]
+    assert jwt.decode(new, options={"verify_signature": False})["rme"] is True
+    assert "Max-Age=" in response.headers.get_list("set-cookie")[0]
+    assert api_client.get(api_routes.users_self, headers=bearer(new)).status_code == 200
+    assert api_client.post(api_routes.auth_refresh, headers=bearer("nope")).status_code == 401
+
+    api_token = api_client.post(api_routes.users_api_tokens, json={"name": "t"}, headers=unique_user.token).json()
+    refused = api_client.post(api_routes.auth_refresh, headers=bearer(api_token["token"]))
+    assert refused.status_code == 400
+    # other tests assume the first API token id is free
+    api_client.delete(api_routes.users_api_tokens_token_id(api_token["id"]), headers=unique_user.token)
+
+
+def test_logout_clears_cookie(api_client: TestClient, unique_user: TestUser):
+    response = api_client.post(api_routes.auth_logout, headers=unique_user.token)
+    cookie = response.headers.get_list("set-cookie")[0]
+    assert cookie.startswith("mealie.access_token=")
+    assert "Max-Age=0" in cookie
+
+
+def fake_request(scheme: str, headers: dict[str, str]) -> SimpleNamespace:
+    return SimpleNamespace(url=SimpleNamespace(scheme=scheme), headers=headers)
+
+
+def test_session_cookie_attrs():
+    assert session_cookie_attrs(fake_request("http", {"x-forwarded-proto": "https, http"}))["secure"] is True  # type: ignore
+    assert session_cookie_attrs(fake_request("http", {"x-forwarded-proto": "http, https"}))["secure"] is False  # type: ignore
+    embedded = session_cookie_attrs(
+        fake_request("http", {"x-forwarded-proto": "https", "x-mealie-embedded": "true"})  # type: ignore
+    )
+    assert (embedded["samesite"], embedded["partitioned"]) == ("none", True)
+    plain = session_cookie_attrs(fake_request("http", {"x-mealie-embedded": "true"}))  # type: ignore
+    assert (plain["samesite"], plain["partitioned"]) == ("lax", False)
+
+
+def test_password_change_ends_sessions(api_client: TestClient, unique_user: TestUser):
+    old = login(api_client, unique_user, False).json()["access_token"]
+    api_token = api_client.post(api_routes.users_api_tokens, json={"name": "t"}, headers=unique_user.token).json()
+    time.sleep(1.1)
+    response = api_client.put(
+        api_routes.users_password,
+        json={"currentPassword": unique_user.password, "newPassword": "new-password-123"},
+        headers=bearer(old),
+    )
+    assert response.status_code == 200
+    assert api_client.get(api_routes.users_self, headers=bearer(old)).status_code == 401
+    fresh = login(api_client, unique_user, False, "new-password-123").json()["access_token"]
+    assert api_client.get(api_routes.users_self, headers=bearer(fresh)).status_code == 200
+    assert api_client.get(api_routes.users_self, headers=bearer(api_token["token"])).status_code == 200
+    api_client.delete(api_routes.users_api_tokens_token_id(api_token["id"]), headers=bearer(fresh))

